import React from "react";
import {Routes, Route, Navigate } from "react-router-dom";
import Login from "./UserAuthentication/login/Login";
import Register from "./UserAuthentication/registration/Register";
import Home from "./HomePage/src/HomeApp"
import { useAuthentication } from "./UserAuthentication/userauthentication"
import AboutUs from "./HomePage/pages/AboutUs";
import FAQOther from "./HomePage/pages/FAQOther";
import LandingLayout from "./UserAuthentication/LandingLayout";
import BackgroundWrapper from "./HomePage/pages/BackgroundWrapper";

const PrivateRoute = ({ children }) => {
  const { user, loading } = useAuthentication();

  if (loading) return <p> Loading...</p>
  return user ? children : <Navigate to="/about-us" replace />
};

function App(){
  const { user, loading } = useAuthentication();

  if (loading) return <p>Loading...</p>;

  return (
    <Routes>
      {/* Default Route: Redirect to login page if user is not authenticated */}
      <Route path="/" element={user ? <Navigate to="/home" replace /> : <Navigate to="/about-us" replace />} />

      {/* Public Routes */}
      <Route path="/login" element={<Login />} />
      <Route path="/register" element={<Register />} />

      <Route element={<LandingLayout />}>
        <Route path='/faqother' element={<FAQOther />} />
        <Route path='/about-us' element={<AboutUs />} />
      </Route>

      {/* Protected Route */}
      <Route path="/home/*" element={<PrivateRoute> <BackgroundWrapper> <Home /> </BackgroundWrapper> </PrivateRoute>} />

      {/* Catch-all: Redirect unknown routes to the login page */}
      <Route path="*" element={<Navigate to="/login" replace />} />
    </Routes>
  );
}

export default App;

import React, { useEffect, useRef, useState } from "react";
import "./chat.css";
import EmojiPicker from "emoji-picker-react";
import { arrayUnion, doc, getDoc, onSnapshot, updateDoc } from "firebase/firestore";
import { db } from "../../lib/firebase";
import { useChatStore } from "../../lib/chatStore";
import { useUserStore } from "../../lib/userStore";
import { format } from "date-fns";


const Chat = () => {
  const [chat, setChat] = useState(null);
  const [open, setOpen] = useState(false);
  const [text, setText] = useState("");
  const [img, setImg] = useState({
    file: null,
    url: "",
  });

  const currentUser = useUserStore((state)=>state.currentUser); //fetches Zustand state
  const { chatId, user, isCurrentUserBlocked, isReceiverBlocked } = useChatStore();
  console.log("Chat ID in Chat.jsx:", chatId); // Debugging log
  console.log("User in Chat.jsx:", user); // Debugging log
  const endRef = useRef(null);

  //console log when chatId or user is changed
  useEffect(() => {
    console.log("Chat ID changed: ", chatId);
    console.log("User updated: ", user);
  }, [chatId, user]);

  //preventing infinite loop
  useEffect(() => {
    if (!chatId) {
      console.warn("Chat ID is null in Chat.jsx, skipping snapshot.");
      return;
    }

    const chatRef = doc(db, "chats", chatId);
    const unsubscribe = onSnapshot(doc(db, "chats", chatId), (res) => {
      setChat(res.data());
      endRef.current?.scrollIntoView({ behavior: "smooth" });
    });

    return () => {
      unsubscribe();
    };
  }, [chatId]);

  const handleEmoji = (e) => {
    setText((prev) => prev + e.emoji);
    setOpen(false);
  };

  const handleImg = (e) => {
    if (e.target.files[0]) {
      setImg({
        file: e.target.files[0],
        url: URL.createObjectURL(e.target.files[0]),
      });
    }
  };

  const handleSend = async () => {
    if (text === "") return;

    let imgUrl = null;

    try {
      if (img.file) {
        imgUrl = await upload(img.file);
      }

      await updateDoc(doc(db, "chats", chatId), {
        messages: arrayUnion({
          senderId: currentUser.id,
          text,
          createdAt: new Date(),
          ...(imgUrl && { img: imgUrl }),
        }),
      });

      const userIDs = [currentUser.id, user.id];

      userIDs.forEach(async (id) => {
        const userChatsRef = doc(db, "userchats", id);
        const userChatsSnapshot = await getDoc(userChatsRef);

        if (userChatsSnapshot.exists()) {
          const userChatsData = userChatsSnapshot.data();

          const chatIndex = userChatsData.chats.findIndex(
            (c) => c.chatId === chatId
          );

          userChatsData.chats[chatIndex].lastMessage = text;
          userChatsData.chats[chatIndex].isSeen =
            id === currentUser.id ? true : false;
          userChatsData.chats[chatIndex].updatedAt = Date.now();

          await updateDoc(userChatsRef, {
            chats: userChatsData.chats,
          });
        }
      });
    } catch (err) {
      console.log(err);
    } finally{
    setImg({
      file: null,
      url: "",
    });
    setText("");
    }
  };

  return (
    <div className="chat">
      <div className="top">
        <div className="user">
          <img src={user?.avatar || "../../../../public/DirectMessaging/avatar.png"} alt="" />
          <div className="texts">
            <span>{user?.username}</span>
            <p>ReceiverId</p>
          </div>
        </div>
        <div className="icons">
          <img src="../../../../public/DirectMessaging/phone.png" alt="" />
          <img src="../../../../public/DirectMessaging/video.png" alt="" />
          <img src="../../../../public/DirectMessaging/info.png" alt="" />
        </div>
      </div>
      <div className="center">
        {chat?.messages?.map((message, index) => (
          <div
            key={message?.createdAt?.seconds || index}
            className={message.senderId === currentUser?.id ? "message own" : "message"}
          >
            <div className="texts">
              {message.img && <img src={message.img} alt="" />}
              <p>{message.text}</p>
              <span>
  {message.createdAt
? format(new Date(message.createdAt.seconds * 1000), "MMM dd, yyyy HH:mm")
: "Just now"}
</span>
            </div>
          </div>
        ))}
        {img.url && (
          <div className="message own">
            <div className="texts">
              <img src={img.url} alt="" />
            </div>
          </div>
        )}
        <div ref={endRef}></div>
      </div>
      <div className="bottom">
        <div className="icons">
          <label htmlFor="file">
            <img src="../../../../public/DirectMessaging/img.png" alt="" />
          </label>
          <input
            type="file"
            id="file"
            style={{ display: "none" }}
            onChange={handleImg}
          />
          <img src="../../../../public/DirectMessaging/camera.png" alt="" />
          <img src="../../../../public/DirectMessaging/mic.png" alt="" />
        </div>
        <input
          type="text"
          placeholder={
            isCurrentUserBlocked || isReceiverBlocked
              ? "You cannot send a message"
              : "Type a message..."
          }
          value={text}
          onChange={(e) => setText(e.target.value)}
          disabled={isCurrentUserBlocked || isReceiverBlocked}
        />
        <div className="emoji">
          <img
            src="../../../../public/DirectMessaging/emoji.png"
            alt=""
            onClick={() => setOpen((prev) => !prev)}
          />
          <div className="picker">
            <EmojiPicker open={open} onEmojiClick={handleEmoji} />
          </div>
        </div>
        <button
          className="sendButton"
          onClick={handleSend}
          disabled={isCurrentUserBlocked || isReceiverBlocked}
        >
          Send
        </button>
      </div>
    </div>
  );
console.log("Chat.jsx");
};

export default Chat;

