import { useEffect, useState } from "react";
import "./chatList.css";
import AddUser from "./addUser/addUser";
import { useUserStore } from "../../../lib/userStore";
import { doc, getDoc, onSnapshot, setDoc } from "firebase/firestore";
import { db } from "../../../lib/firebase";
import { useChatStore } from "../../../lib/chatStore";
import CreateGroup from "./createGroup/createGroup";

const ChatList = () => {
  const [chats, setChats] = useState([]);
  const [addMode, setAddMode] = useState(false);
  const [addModeGroup, setAddModeGroup] = useState(false);
  const [input, setInput] = useState("");

  const currentUser = useUserStore((state) => state.currentUser);
  const { changeChat } = useChatStore();

  if (!currentUser) return <p>Error: No user found.</p>;

  useEffect(() => {
    if (!currentUser || !currentUser.id) {
      console.warn("currentUser is null or undefined, skipping snapshot.");
      return;
    }

    console.log("Fetching chats for user:", currentUser.id);
    const userChatsRef = doc(db, "userchats", currentUser.id);

    const unSub = onSnapshot(userChatsRef, async (res) => {
      if (!res.exists()) {
        console.warn("No userchats document found for user:", currentUser.id);
        await setDoc(userChatsRef, { chats: [] }); // Create empty doc if needed
        setChats([]);
        return;
      }

      const chatArray = res.data().chats || [];
      console.log("Chats found for user:", chatArray);

      const uniqueChats = {};
      chatArray.forEach((chat) => {
        if (
          !uniqueChats[chat.receiverId] ||
          chat.updatedAt > uniqueChats[chat.receiverId].updatedAt
        ) {
          uniqueChats[chat.receiverId] = chat;
        }
      });

      const chatData = await Promise.all(
        Object.values(uniqueChats).map(async (chatItem) => {
          if (!chatItem.receiverId) return null;

          try {
            const userDocRef = doc(db, "users", chatItem.receiverId);
            const userDocSnap = await getDoc(userDocRef);

            if (userDocSnap.exists()) {
              return { ...chatItem, user: userDocSnap.data() };
            } else {
              console.warn("User document not found for receiverId:", chatItem.receiverId);
              return null;
            }
          } catch (error) {
            console.error("Error fetching user document:", error);
            return null;
          }
        })
      );

      setChats(
        chatData
          .filter((chat) => chat !== null)
          .sort((a, b) => (b.updatedAt || 0) - (a.updatedAt || 0))
      );
    });

    return () => {
      unSub();
    };
  }, [currentUser?.id]);

  const handleSelect = async (chat) => {
    console.log("Selected Chat:", chat);
    if (chat.chatId) {
      changeChat(chat.chatId, { id: chat.receiverId });
    }
  };

  const filteredChats = chats.filter((c) =>
    c.user?.username?.toLowerCase().includes(input.toLowerCase())
  );

  return (
    <div className="chatList">
      <div className="search">
        <div className="searchBar">
          <img src="../../../../public/DirectMessaging/search.png" alt="Search" />
          <input
            type="text"
            style={{ color: "white" }}
            placeholder="Search"
            onChange={(e) => setInput(e.target.value)}
          />
        </div>

        <img
          src={
            addMode
              ? "../../../../public/DirectMessaging/minus.png"
              : "../../../../public/DirectMessaging/plus.png"
          }
          alt=""
          className="add"
          onClick={() => setAddMode((prev) => !prev)}
        />

      </div>

      {addModeGroup}

      {filteredChats.length === 0 ? (
        <p>No chats found. Add a user to start messaging!</p>
      ) : (
        filteredChats.map((chat, index) => {
          console.log("🔍 Chat:", chat);
          return (
            <div
              key={`${chat.chatId}_${index}`}
              className="item"
              onClick={() => handleSelect(chat)}
            >
              <img
                src={chat.user?.avatar || "../../../../public/DirectMessaging/avatar.png"}
                alt=""
              />
              <div className="texts">
                <span>{chat.user?.username || chat.user?.email || "Unknown User"}</span>
                <p>{chat.lastMessage || "No messages yet"}</p>
              </div>
            </div>
          );
        })
      )}

      {addMode && <AddUser />}
    </div>
  );
};

export default ChatList;

import "./addUser.css";
import { db } from "../../../../lib/firebase";
import { arrayUnion, collection, doc, getDoc, getDocs, query, serverTimestamp, setDoc, updateDoc, where,} from "firebase/firestore";
import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { useUserStore } from "../../../../lib/userStore";
import { toast } from "react-toastify";
import { useChatStore } from "../../../../lib/chatStore";
import { auth } from "../../../../lib/firebase";
const AddUser = ({ setAddMode }) => {
    const [input, setInput] = useState("");
    const [searchedUser, setSearchedUser] = useState(null);
    const currentUser = useUserStore((state) => state.currentUser);
    const { startChat } = useChatStore();

    const handleSearch = async () => {
        if (!input) {
            toast.error("Please enter a username or ID.");
            return;
        }

        const usersRef = collection(db, "users");
        const q = query(usersRef, where("username", "==", input)); // 🔍 Search by username
        const querySnapshot = await getDocs(q);

        if (!querySnapshot.empty) {
            setSearchedUser(querySnapshot.docs[0].data()); // ✅ Set first matching user
        } else {
            toast.error("User not found.");
            setSearchedUser(null);
        }
    };

    const handleAdd = async () => {
        if (!searchedUser) {
            toast.error("No user selected.");
            return;
        }

        const receiverId = searchedUser.id;
        if (receiverId === currentUser.id) {
            toast.error("You cannot start a chat with yourself.");
            return;
        }

        try {
            const userChatsRef = doc(db, "userchats", currentUser.id);
            const userChatsSnap = await getDoc(userChatsRef);

            if (userChatsSnap.exists()) {
                const existingChats = userChatsSnap.data().chats || [];
                const chatExists = existingChats.some(chat => chat.receiverId === receiverId);

                if (chatExists) {
                    toast.error("You already have a direct messaging thread with this user.");
                    return;
                }
            }

            // ✅ Create new chat
            await startChat(receiverId);
            toast.success("User added successfully!");
        } catch (error) {
            console.error("Error adding user:", error);
            toast.error("Failed to add user.");
        }
    };

    return (
        <div className="addUser">
            <input
                type="text"
                placeholder="Enter user ID or username"
                value={input}
                onChange={(e) => setInput(e.target.value)}
            />
            <button onClick={handleSearch}>Search</button>
            {searchedUser && (
                <div>
                    <p>{searchedUser.username}</p>
                    <button onClick={handleAdd}>Add User</button>
                </div>
            )}
        </div>
    );
};

export default AddUser;

import "./createGroup.css"
import { toast } from "react-toastify";
import { useState } from "react";
import { db } from "../../../../lib/firebase";
import { doc, setDoc } from "firebase/firestore";


const CreateGroup = () => {
        const handleRegister = async e =>{
            e.preventDefault()
            const formData = new FormData(e.target)

            const {chatUsername} = Object.fromEntries(formData);

            try{
                const res = await createUserWithEmailAndPassword(auth, chatUsername);

                await setDoc(doc(db, "chats", res.user.uid), {
                    chatUsername: chatUsername,
                    id : res.user.uid,
                    blocked: [],
                });
                toast.success("Account created! You can now log in!")

                await setDoc(doc(db, "userchats", res.user.uid), {
                    chats: [],
                });

            }catch(err){
                console.log(err)
                toast.error(err.message)
            }
        };
    return(
        <div className="item">
            <h4>Create a Group Chat</h4>
            <form onSubmit={handleRegister}>
                <input type="chatname" placeholder="ChatName" name="chatname" />
                <button>Create</button>
            </form>
        </div>
    );
};


export default CreateGroup;

import { toast } from "react-toastify";
import "./login.css"
import { useState } from "react";
import { createUserWithEmailAndPassword, signInWithEmailAndPassword} from "firebase/auth";
import { auth, db } from "../../lib/firebase";
import { doc, setDoc } from "firebase/firestore";
import { create } from "zustand";



const Login = () => {
    const [loading, setLoading] = useState(false);

    const handleRegister = async e =>{
        e.preventDefault()
        const formData = new FormData(e.target)

        const { firstName, lastName, username, email, password} = Object.fromEntries(formData);

        try{
            const res = await createUserWithEmailAndPassword(auth, email, password);

            await setDoc(doc(db, "users", res.user.uid), {
                firstName: firstName,
                lastName: lastName,
                username: username,
                email: email,
                createdAt: new Date(),
                id : res.user.uid,
                admin: false,
                blocked: [],
            });
            toast.success("Account created! You can now log in!")

            await setDoc(doc(db, "userchats", res.user.uid), {
                chats: [],
            });

        }catch(err){
            console.log(err)
            toast.error(err.message)
        }
    };

    const handleLogin = async(e) =>{
        e.preventDefault();
        setLoading(true);

        const formData = new FormData(e.target)
        const {email,password} = Object.fromEntries(formData);

        try{
            await signInWithEmailAndPassword(auth,email,password);

        }catch (err){
            console.log(err);
            toast.error(err.message);
        }
        finally{
            setLoading(false);
        }
    }

    return(
        <div className="login">
            <div className="item">
                <h2>WELCOME BACK!</h2>
                <form onSubmit={handleLogin}>
                    <input type="text" placeholder="Email" name="email" />
                    <input type="password" placeholder="Password" name="password" />
                    <button>Sign In</button>
                </form>
            </div>
            <div className="separator"></div>
            <div className="item">
                <h2>Create an Account</h2>
                <form onSubmit={handleRegister}>
                    <input type="username" placeholder="Username" name="username" />
                    <input type="text" placeholder="Email" name="email" />
                    <input type="password" placeholder="Password" name="password" />
                    <button>Sign Up</button>
                </form>
            </div>
        </div>
    );
};

export default Login;

